// Original procedural pixel artwork. All drawing uses an integer 640 x 320 grid.
// A single cached canvas; animation is a lightweight CSS rain layer, never a render loop.
export function drawScene(canvas,room=false){if(!canvas)return;const c=canvas.getContext('2d');canvas.width=640;canvas.height=320;c.imageSmoothingEnabled=false;let seed=729;
const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};const rect=(x,y,w,h,col)=>{c.fillStyle=col;c.fillRect(Math.floor(x),Math.floor(y),Math.ceil(w),Math.ceil(h))};const line=(x,y,x2,y2,col)=>{c.strokeStyle=col;c.lineWidth=1;c.beginPath();c.moveTo(Math.round(x)+.5,Math.round(y)+.5);c.lineTo(Math.round(x2)+.5,Math.round(y2)+.5);c.stroke()};
const sign=(text,x,y,w,col)=>{rect(x-2,y-2,w+4,15,'#1b1736');rect(x,y,w,11,col);rect(x+1,y+1,w-2,9,'#222137');c.fillStyle=col;c.font='6px Pixel, monospace';c.textBaseline='top';c.fillText(text,x+4,y+3)};
for(let y=0;y<240;y++)rect(0,y,640,1,y<80?'#161b3d':y<140?'#27254f':y<190?'#423054':'#593951');
for(let i=0;i<130;i++){const x=rand()*640,y=rand()*160;rect(x,y,rand()>.95?2:1,1,rand()>.5?'#6c6389':'#aba2b1')}
rect(520,28,15,15,'#ccb897');rect(518,31,19,9,'#ccb897');rect(526,27,7,1,'#ccb897');rect(530,28,6,4,'#161b3d');
for(let i=0;i<32;i++){const x=i*23-8,h=30+rand()*82,w=16+rand()*16;rect(x,185-h,w,h,'#2b284d');rect(x+4,180-h,w-8,5,'#2b284d');for(let yy=190-h;yy<180;yy+=9)for(let xx=x+3;xx<x+w-2;xx+=6)if(rand()>.52)rect(xx,yy,2,2,'#56507b');if(rand()>.5)rect(x+w/2,165-h,1,20,'#454064')}
// Middle skyline, antennas, air-conditioning units and uneven lit windows.
for(let i=0;i<16;i++){const x=i*44-10,h=55+rand()*100,w=28+rand()*22;rect(x,245-h,w,h,'#191c38');rect(x,245-h,2,h,'#493656');rect(x+3,241-h,w-6,4,'#292544');for(let yy=251-h;yy<237;yy+=9)for(let xx=x+6;xx<x+w-3;xx+=7){const z=rand();rect(xx,yy,3,4,z>.8?'#729b9e':z>.58?'#755173':'#292b47')}if(i%3===0){rect(x+10,224-h,1,19,'#69718c');rect(x+8,222-h,5,2,'#ef8dba')}}
// Each foreground building corresponds to a destination in the OS.
const buildings=[{x:28,y:151,w:83,h:104,color:'#7de8e6',name:'LAB / 02'},{x:143,y:113,w:88,h:142,color:'#e97bc0',name:'LINGUA'},{x:272,y:177,w:79,h:78,color:'#87c9ed',name:'FOCUS'},{x:383,y:139,w:73,h:116,color:'#9f93e5',name:'ARCHIVE'},{x:476,y:186,w:95,h:69,color:'#edbe83',name:'HOME'}];
buildings.forEach((b,i)=>{rect(b.x,b.y,b.w,b.h,'#111c2c');rect(b.x,b.y,3,b.h,'#3b3250');rect(b.x+3,b.y+3,b.w-6,4,b.color);rect(b.x+5,b.y+10,b.w-10,b.h-13,'#20233b');rect(b.x+b.w-7,b.y+5,4,b.h-5,'#39334f');for(let yy=b.y+19;yy<248;yy+=17){rect(b.x+4,yy+10,b.w-10,2,'#111725');for(let xx=b.x+10;xx<b.x+b.w-12;xx+=13){const on=rand()>.3;rect(xx,yy,8,9,'#0d192a');if(on){rect(xx+1,yy+1,6,6,rand()>.6?'#ecc084':b.color);rect(xx+3,yy+1,1,7,'#292840')}rect(xx-1,yy+9,10,1,'#3a465c')}}rect(b.x+9,b.y-7,14,7,'#33304d');rect(b.x+11,b.y-5,10,2,'#595168');rect(b.x+b.w-16,b.y-24,1,24,'#766686');rect(b.x+b.w-18,b.y-24,5,2,b.color);sign(b.name,b.x+6,b.y+34,b.w-12,b.color);rect(b.x+b.w/2-9,235,18,20,'#101424');rect(b.x+b.w/2-7,237,14,17,b.color);rect(b.x+b.w/2-1,237,2,17,'#162238');if(i===1){rect(b.x-11,b.y+22,12,60,'#b85aab');rect(b.x-9,b.y+24,8,56,'#39234f');for(let y=b.y+28;y<b.y+76;y+=10){rect(b.x-7,y,4,6,'#f699d3');rect(b.x-6,y+1,2,2,'#39234f')}}});
// Comms tower, suspended cables and neon transit platform.
rect(605,90,4,165,'#3a3b58');rect(591,128,32,4,'#787999');rect(596,119,23,3,'#8d89ad');rect(601,104,13,2,'#b67bae');rect(606,75,2,16,'#dda9d0');rect(604,73,6,3,'#d7a4dc');for(let y=143;y<244;y+=13)line(606,y,615,y+8,'#505575');
line(0,155,40,171,'#0a1424');line(40,171,170,158,'#0a1424');line(170,158,290,180,'#0a1424');line(348,164,422,183,'#0a1424');line(422,183,605,143,'#0a1424');
rect(0,256,640,4,'#66506d');rect(0,260,640,2,'#a17696');rect(0,262,640,6,'#1a2639');rect(0,268,640,52,'#111b30');rect(0,277,640,2,'#294056');rect(0,308,640,2,'#54738d');for(let i=0;i<260;i++){const x=rand()*640,y=270+rand()*44;rect(x,y,2+rand()*16,1,['#213449','#394057','#3b354f','#36515e','#4f405b'][i%5])}
for(const b of buildings)for(let i=0;i<18;i++)rect(b.x+rand()*b.w,271+rand()*33,3+rand()*11,1,i%4===0?b.color:'#3a3a59');
for(let x=9;x<640;x+=125){rect(x,219,2,37,'#555873');rect(x-7,218,15,2,'#9ba5b5');rect(x-6,220,13,2,'#80d7df');rect(x-8,254,18,2,'#53657f')}
// Small human silhouettes, a parked scooter, rails, planter boxes.
for(let x of [67,125,249,365,468,582]){rect(x,244,3,4,'#bda4b2');rect(x-1,248,5,7,'#344566');rect(x-1,255,2,4,'#131825');rect(x+2,255,2,4,'#131825')}
rect(234,252,15,3,'#af7bba');rect(237,248,2,5,'#84749d');rect(243,251,2,5,'#84749d');rect(233,255,4,3,'#090f23');rect(245,255,4,3,'#090f23');for(let x of [118,357,461]){rect(x,249,9,7,'#564354');rect(x+1,242,6,8,'#426965');rect(x+3,238,3,7,'#608474')}
if(room){const city=c.getImageData(0,0,640,320);rect(0,0,640,320,'#1a1b30');for(let y=0;y<270;y+=12)rect(0,y,640,1,'#25243b');c.putImageData(city,0,0,260,38,240,163);rect(254,31,252,7,'#62556f');rect(254,201,252,8,'#62556f');rect(254,31,7,177,'#62556f');rect(500,31,7,177,'#62556f');rect(376,34,6,169,'#544c67');rect(258,121,246,5,'#544c67');rect(0,272,640,48,'#30263d');for(let y=274;y<320;y+=10)rect(0,y,640,1,'#4c3550');for(let x=0;x<640;x+=65)rect(x,274,1,46,'#574057');rect(37,59,111,5,'#796074');for(let x=42;x<140;x+=11){rect(x,32+(x%4)*4,8,25-(x%4)*4,['#826782','#68a4a5','#ac947c'][x%3]);rect(x+1,47,6,1,'#c4b6b0')}sign('SLOW DOWN',41,80,94,'#d68ba7');rect(26,196,161,54,'#534766');rect(20,211,15,49,'#716081');rect(176,211,15,49,'#716081');rect(36,202,62,31,'#786783');rect(105,202,62,31,'#786783');rect(32,249,153,7,'#383344');rect(38,256,5,16,'#837080');rect(166,256,5,16,'#837080');rect(272,231,170,7,'#917387');rect(280,238,6,36,'#64516b');rect(430,238,6,36,'#64516b');rect(302,183,69,42,'#4a4d66');rect(306,187,61,33,'#172a3b');rect(310,192,42,2,'#6ccaba');rect(310,199,25,2,'#839bd0');rect(310,207,47,2,'#b785b5');rect(332,225,10,5,'#60617a');rect(388,220,12,11,'#a69fa7');rect(400,222,4,6,'#a69fa7');rect(530,189,29,16,'#8da0ac');rect(544,205,2,62,'#89768b');rect(530,267,30,4,'#89768b');rect(574,232,27,41,'#765564');rect(579,204,14,30,'#47796b');rect(571,216,28,8,'#60958a');rect(584,189,5,25,'#76a490');rect(220,286,282,15,'#5e4962');rect(229,291,263,3,'#946b84')}
}
export async function mountScene(){const canvas=document.querySelector('#scene');if(canvas){await document.fonts.ready;if(canvas.isConnected)drawScene(canvas,canvas.dataset.room==='true')}}
